cp lib/data.ts /tmp/data.bak && cat > lib/data.ts <<'EOF'
import { connection } from 'next/server'

export async function getInventory() {
  await connection()
  await new Promise((r) => setTimeout(r, 3000))
  return {
    count: Math.floor(Math.random() * 50),
    price: (Math.random() * 100).toFixed(2),
  }
}
EOF
pkill -f "next start" ; npx next build >/dev/null 2>&1 && (npx next start -p 3112 >/tmp/s2.log 2>&1 &) ; sleep 6
curl -s --no-buffer localhost:3112/product | while IFS= read -r line; do
  case "$line" in
    *"Premium Widget"*) echo "[$(date +%s.%N)] TITLE" ;;
    *"Checking availability"*) echo "[$(date +%s.%N)] FALLBACK" ;;
    *"in stock"*) echo "[$(date +%s.%N)] INVENTORY" ;;
  esac
done

